      "name": "left_le_lineMap_iff_nonneg",
      "module_name": "Mathlib.LinearAlgebra.AffineSpace.Ordered",
      "kind": "theorem",
      "type": "∀ {k : Type u_1} {E : Type u_2} [inst : Ring k] [inst_1 : LinearOrder k] [IsStrictOrderedRing k]\n  [inst_3 : AddCommGroup E] [inst_4 : PartialOrder E] [IsOrderedAddMonoid E] [inst_6 : Module k E]\n  [IsStrictOrderedModule k E] {a b : E} {r : k}, a < b → (a ≤ (AffineMap.lineMap a b) r ↔ 0 ≤ r)"
    },
    {
      "name": "finsum_nonneg",
      "module_name": "Mathlib.Algebra.BigOperators.Finprod",
      "kind": "theorem",
      "type": "∀ {α : Sort u_4} {M : Type u_7} [inst : AddCommMonoid M] [inst_1 : PartialOrder M] [IsOrderedAddMonoid M] {f : α → M},\n  (∀ (i : α), 0 ≤ f i) → 0 ≤ ∑ᶠ (i : α), f i"
    },
    {
      "name": "MeasureTheory.SimpleFunc.posPart",
      "module_name": "Mathlib.MeasureTheory.Integral.Bochner.L1",
      "kind": "definition",
      "type": "{α : Type u_1} →\n  {E : Type u_2} →\n    [LinearOrder E] →\n      [Zero E] → [inst : MeasurableSpace α] → MeasureTheory.SimpleFunc α E → MeasureTheory.SimpleFunc α E"
    },
    {
      "name": "map_le_lineMap_iff_slope_le_slope_left",
      "module_name": "Mathlib.LinearAlgebra.AffineSpace.Ordered",
      "kind": "theorem",
      "type": "∀ {k : Type u_1} {E : Type u_2} [inst : Field k] [inst_1 : LinearOrder k] [inst_2 : AddCommGroup E]\n  [inst_3 : PartialOrder E] [IsOrderedAddMonoid E] [inst_5 : Module k E] [IsStrictOrderedModule k E]\n  [PosSMulReflectLE k E] {f : k → E} {a b r : k},\n  0 < r * (b - a) →\n    (f ((AffineMap.lineMap a b) r) ≤ (AffineMap.lineMap (f a) (f b)) r ↔\n      slope f a ((AffineMap.lineMap a b) r) ≤ slope f a b)"
    },
    {
      "name": "AddValuation.map_le_sum",
      "module_name": "Mathlib.RingTheory.Valuation.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u_3} {Γ₀ : Type u_4} [inst : Ring R] [inst_1 : LinearOrderedAddCommMonoidWithTop Γ₀] (v : AddValuation R Γ₀)\n  {ι : Type u_6} {s : Finset ι} {f : ι → R} {g : Γ₀}, (∀ i ∈ s, g ≤ v (f i)) → g ≤ v (∑ i ∈ s, f i)"
    },
    {
      "name": "lowerBounds_smul_of_neg",
      "module_name": "Mathlib.Algebra.Order.Module.Pointwise",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} [inst : Field α] [inst_1 : LinearOrder α] [IsStrictOrderedRing α]\n  [inst_3 : AddCommGroup β] [inst_4 : PartialOrder β] [IsOrderedAddMonoid β] [inst_6 : Module α β] [PosSMulMono α β]\n  {s : Set β} {a : α}, a < 0 → lowerBounds (a • s) = a • upperBounds s"
    }
  ]
